from solution import minimum_Length


def test_issue_example_mnm():
    """Example: minimum_Length('mnm') == 1."""
    assert minimum_Length("mnm") == 1  # 3-2=1


def test_issue_empty_string():
    """Minimize the length of the string leaves empty string at 0."""
    assert minimum_Length("") == 0  # 0=0


def test_issue_single_character():
    """Minimize length by removing occurrence of only one character from single char."""
    assert minimum_Length("z") == 0  # 1-1=0


def test_issue_all_same_characters():
    """Minimize length by removing occurrence of only one character removes all same."""
    assert minimum_Length("aaaa") == 0  # 4-4=0


def test_issue_all_distinct_characters():
    """Minimize length by removing occurrence of only one character from all distinct."""
    assert minimum_Length("abcd") == 3  # 4-1=3


def test_issue_tie_two_characters():
    """Minimize length by removing occurrence of only one character with tie."""
    assert minimum_Length("aabb") == 2  # 4-2=2


def test_issue_removes_most_frequent_small():
    """Minimize length by removing occurrence of only one character picks most frequent."""
    assert minimum_Length("aabbc") == 3  # 5-2=3


def test_issue_removes_most_frequent_middle():
    """Minimize length by removing occurrence of only one character picks most frequent."""
    assert minimum_Length("abcccb") == 3  # 6-3=3


def test_issue_longer_mixed_frequencies():
    """Minimize length by removing occurrence of only one character from longer string."""
    assert minimum_Length("aaabbbcc") == 5  # 8-3=5


def test_contract_callable_with_one_argument():
    """Public interface minimum_Length(s) is callable with one argument."""
    assert callable(minimum_Length)
    assert minimum_Length("ab") == 1  # 2-1=1


def test_contract_returns_int():
    """Minimized length is returned as an integer length."""
    assert isinstance(minimum_Length("aabb"), int)


def test_contract_result_within_bounds():
    """Minimized length cannot exceed the original string length."""
    assert minimum_Length("aabbc") <= 5  # len=5
